import {cards,topics,questions,dailyTopics,readers,articles} from './data.js';
import {escapeHtml as E,shuffle,makeDraw,dayKey,interpret,validReading,readStore,writeStore,history,saveReading,readingText,cardArt,backArt} from './core.js';
const $=s=>document.querySelector(s); const root=$('#app');
let flow=null,libraryPage=1,librarySearch='',librarySuit='all';
const routes={home:'/',three:'/boi-tarot/',daily:'/boi-bai-tarot-hom-nay/',custom:'/boi-bai-tarot-chuyen-sau/',library:'/y-nghia-78-la-bai-tarot/',readers:'/cac-tarot-reader/',history:'/nhat-ky/',blog:'/huong-dan/'};
function link(route,text,cls=''){return `<a href="${route}" data-link class="${cls}">${text}</a>`;}
function toast(msg){$('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=msg;document.body.append(el);setTimeout(()=>el.remove(),4500);}
function title(text,desc){document.title=`${text} | Tarot Gợi Mở`;document.querySelector('meta[name="description"]').content=desc||'Tarot Gợi Mở — trải bài 78 lá, khám phá cảm xúc và những hướng đi của riêng bạn.';}
function pageHead(kicker,heading,desc){return `<div class="page-head"><span class="eyebrow">${kicker}</span><h1>${heading}</h1><p>${desc}</p></div>`;}
const cardLink=c=>`/la-bai/${c.id}/`;
function header(){return `<a class="skip-link" href="#main">Đến nội dung chính</a><header><div class="nav">${link('/',`<span class="logo-mark">☾</span><span><strong>Tarot Gợi Mở</strong><small>LẮNG NGHE ĐIỀU BÊN TRONG</small></span>`,'logo')}<button class="menu" aria-label="Mở menu" aria-expanded="false">☰</button><nav aria-label="Điều hướng chính">${link('/','Trang chủ')}${link(routes.three,'Trải bài Tarot')}${link(routes.daily,'Tarot hôm nay')}${link(routes.library,'78 lá bài')}${link(routes.blog,'Góc chiêm nghiệm')}${link(routes.history,'Nhật ký ↗','nav-journal')}</nav></div></header>`;}
function footer(){return `<footer><div class="container"><div class="footer-top">${link('/',`<span class="logo-mark">☾</span><span><strong>Tarot Gợi Mở</strong><small>LẮNG NGHE ĐIỀU BÊN TRONG</small></span>`,'logo')}<div class="footer-links">${link(routes.readers,'Phong cách đọc')}${link('/gioi-thieu/','Về Gợi Mở')}${link('/quyen-rieng-tu/','Quyền riêng tư')}${link(routes.blog,'Hướng dẫn')}</div></div><p class="footer-note">Tarot là một gợi ý để chiêm nghiệm, không phải lời khẳng định về tương lai. Nội dung tự động từ thư viện biên soạn, không thay thế tư vấn y tế, pháp lý hay tài chính.</p><div class="footer-bottom"><span>© ${new Date().getFullYear()} Tarot Gợi Mở. Một khoảng lặng dành cho bạn.</span><span>78 lá bài · Không cần tài khoản · Miễn phí</span></div></div></footer>`;}
function modeCards(){return `<div class="mode-grid">${[
[routes.three,'△','KHÁM PHÁ GÓC NHÌN','Trải bài 3 lá','Bối cảnh, hiện tại và hướng đi. Nhìn câu chuyện của bạn qua ba lá bài được chọn bằng trực giác.','Bắt đầu trải bài'],
[routes.daily,'☀','MỘT THÔNG ĐIỆP MỖI NGÀY','Tarot hôm nay','Một lá bài, một lời nhắc nhỏ. Chậm lại để lắng nghe điều bạn muốn dành sự chú ý hôm nay.','Rút lá bài hôm nay'],
[routes.custom,'✧','DÀNH RIÊNG CHO BẠN','Tự đặt câu hỏi','Viết điều đang ở trong lòng. Chọn phong cách đọc và nhận một góc nhìn để tự chiêm nghiệm.','Đặt câu hỏi của bạn']].map(a=>link(a[0],`<span class="mode-icon">${a[1]}</span><small>${a[2]}</small><h3>${a[3]}</h3><p>${a[4]}</p><div class="mode-foot"><span>${a[5]}</span><span>↗</span></div>`,'mode-card')).join('')}</div>`;}
function articleCards(list){return `<div class="knowledge">${list.map(a=>link(`/huong-dan/${a.slug}/`,`<div class="article-art">${a.icon}</div><div class="article-body"><small>${a.tag}</small><h3>${a.title}</h3><p>${a.intro}</p><span class="text-link">Đọc tiếp ↗</span></div>`,'article')).join('')}</div>`;}
function home(){title('Bói bài Tarot online miễn phí');return `<div class="container"><div class="hero"><div><span class="eyebrow">MỘT KHOẢNG LẶNG · MỘT GÓC NHÌN MỚI</span><h1>Lắng nghe vũ trụ.<br><em>Thấu hiểu chính mình.</em></h1><p>Có những câu trả lời bắt đầu từ một khoảnh khắc tĩnh lặng. Để những lá bài mở ra góc nhìn mới về tình yêu, công việc và hành trình của riêng bạn.</p><div class="hero-actions">${link(routes.three,'Trải bài của bạn <span>↗</span>','btn')}${link(routes.daily,'Lá bài hôm nay','btn secondary')}</div><div class="hero-note"><span>Hoàn toàn miễn phí</span><span>Không cần đăng nhập</span></div></div><div class="hero-art" aria-label="Minh họa ba lá bài Tarot"><div class="orbit"></div><div class="hero-card left">${cardArt(cards[17])}</div><div class="hero-card right">${cardArt(cards[19])}</div><div class="hero-card center">${cardArt(cards[18])}</div><span class="spark s1">✧</span><span class="spark s2">✦</span><span class="art-caption">AS ABOVE, SO BELOW</span></div></div></div><div class="ribbon"><span><b>✦</b> 78 LÁ BÀI TAROT</span><span><b>✦</b> 17 CHỦ ĐỀ CHIÊM NGHIỆM</span><span><b>✦</b> KHÔNG GIAN RIÊNG CỦA BẠN</span></div><div class="container"><section><div class="section-head"><div><span class="eyebrow">CHỌN CÁCH BẠN MUỐN BẮT ĐẦU</span><h2>Một trải bài, nhiều điều gợi mở.</h2><p>Không cần biết trước câu trả lời. Chỉ cần một câu hỏi chân thành.</p></div></div>${modeCards()}</section></div><section class="daily-section"><div class="container daily-layout"><div><span class="eyebrow">HÔM NAY, BẠN THẾ NÀO?</span><h2>Một lá bài.<br>Một lời nhắn cho ngày mới.</h2><p>Chọn điều bạn đang quan tâm và đón nhận một thông điệp nhẹ nhàng. Lá bài của bạn được lưu lại trong ngày.</p>${link(routes.daily,'Khám phá hôm nay ↗','btn secondary')}</div><div class="daily-cards">${dailyTopics.map(id=>{const t=topics.find(t=>t.id===id);return link(`${routes.daily}?topic=${id}`,`<div class="mini-back">${backArt}</div><span>${t.name}</span>`,'daily-item')}).join('')}</div></div></section><div class="container"><section><div class="section-head"><div><span class="eyebrow">ĐIỀU GÌ ĐANG Ở TRONG LÒNG BẠN?</span><h2>Mỗi băn khoăn đều xứng đáng được lắng nghe.</h2></div>${link(routes.three,'Tất cả chủ đề ↗','text-link')}</div><div class="topics-grid">${topics.slice(0,12).map(t=>link(`${routes.three}?topic=${t.id}`,`<span>${t.icon}</span>${t.name}`,'topic-tile')).join('')}</div></section><section style="padding-top:10px"><div class="section-head"><div><span class="eyebrow">GÓC CHIÊM NGHIỆM</span><h2>Hiểu lá bài. Hiểu mình hơn.</h2></div>${link(routes.blog,'Khám phá thêm ↗','text-link')}</div>${articleCards(articles.slice(0,3))}</section><div class="quote-band"><span class="eyebrow">BẠN VẪN LÀ NGƯỜI CHỌN HƯỚNG ĐI</span><h2>“Lá bài gợi mở. Bạn viết tiếp câu chuyện.”</h2><p>Tarot không quyết định thay bạn. Hãy giữ điều hữu ích, kiểm chứng bằng trải nghiệm và bước tiếp theo cách của riêng mình.</p>${link(routes.library,'Khám phá 78 lá bài ↗','text-link')}</div><section style="padding-top:0"><div class="section-head"><div><span class="eyebrow">NHỮNG ĐIỀU BẠN CÓ THỂ MUỐN BIẾT</span><h2>Trước khi bắt đầu.</h2></div></div><div class="faq">${[
['Tôi chưa biết gì về Tarot, có dùng được không?','Có. Chọn chủ đề, đặt câu hỏi, xào và chọn bài. Mỗi kết quả có giải thích bằng tiếng Việt và một gợi ý hành động.'],['Luận giải được tạo ra như thế nào?','Ứng dụng chọn bài ngẫu nhiên từ bộ 78 lá bằng bộ sinh số ngẫu nhiên của trình duyệt. Nội dung lấy từ thư viện biên soạn theo lá bài, chiều xuôi/ngược, chủ đề và phong cách đọc. Đây không phải trò chuyện với người thật hay dịch vụ AI đang kết nối.'],['Tôi có phải trả phí không?','Tất cả trải bài hiện tại đều miễn phí và không giới hạn. Website không thu tiền, không yêu cầu chuyển khoản hay mã mở khóa.'],['Nhật ký của tôi được lưu ở đâu?','Nhật ký chỉ lưu trong trình duyệt trên thiết bị này. Không có tài khoản hay đồng bộ đám mây. Bạn có thể xuất dữ liệu hoặc xóa ở trang Nhật ký.'],['Tarot có dự đoán chắc chắn tương lai không?','Không. Các thông điệp dùng để suy ngẫm và khám phá lựa chọn. Hãy dựa vào thông tin thực tế khi đưa ra quyết định quan trọng.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></section></div>`;}
function newFlow(mode){const query=new URLSearchParams(location.search);const requested=query.get('topic');const allowed=mode==='daily'?dailyTopics:topics.map(t=>t.id);return {mode,step:1,topic:allowed.includes(requested)?requested:mode==='daily'?'love':'self',question:'',reader:query.get('reader')||'gentle',deck:[],selected:[],result:null};}
function readingPage(mode){flow=newFlow(mode);title(mode==='daily'?'Bói bài Tarot hôm nay':mode==='three'?'Trải bài Tarot 3 lá':'Tự đặt câu hỏi Tarot');return `<div class="container">${pageHead(mode==='daily'?'MỘT THÔNG ĐIỆP MỖI NGÀY':mode==='three'?'BA LÁ BÀI · MỘT CÂU CHUYỆN':'ĐIỀU BẠN MUỐN HỎI',mode==='daily'?'Lá bài dành cho hôm nay.':mode==='three'?'Nhìn câu chuyện từ một góc khác.':'Lắng nghe câu hỏi trong lòng.',mode==='daily'?`Ngày ${new Date().toLocaleDateString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'})} · Chọn một chủ đề và dành một phút cho chính mình.`:'Hít thở chậm, tập trung vào điều bạn quan tâm và bắt đầu khi cảm thấy sẵn sàng.')}<div class="reading-shell" id="reading">${flowForm()}</div><div class="narrow"><h2>Cách trải bài của bạn hoạt động</h2><p>${mode==='three'?'Ba lá lần lượt đại diện cho bối cảnh, hiện tại và một hướng đi có thể cân nhắc.':'Một lá bài mở ra một góc nhìn để bạn suy ngẫm.'} Bạn có thể nhận lá xuôi hoặc đảo ngược. Mỗi lá có nội dung riêng; thông điệp được kết hợp với chủ đề đã chọn.</p><p>Luận giải tự động từ thư viện biên soạn, không phải dự đoán chắc chắn hay buổi tư vấn trực tiếp. Tất cả chế độ đang miễn phí.</p></div></div>`;}
function steps(){return `<div class="steps">${['Đặt câu hỏi','Chọn lá bài','Lắng nghe thông điệp'].map((s,i)=>`<span class="${flow.step===i+1?'current':''}"><b>${i+1}</b>${s}</span>`).join('<span>—</span>')}</div>`;}
function flowForm(){const mode=flow.mode;const list=mode==='daily'?topics.filter(t=>dailyTopics.includes(t.id)):topics;return `${steps()}<form id="draw-form"><div class="form-row"><div class="field"><label for="topic">Chủ đề bạn quan tâm</label><select id="topic" name="topic">${list.map(t=>`<option value="${t.id}" ${t.id===flow.topic?'selected':''}>${t.icon} ${t.name}</option>`).join('')}</select></div><div class="field"><label for="reader">Phong cách luận giải</label><select id="reader" name="reader">${readers.map(r=>`<option value="${r.id}" ${r.id===flow.reader?'selected':''}>${r.icon} ${r.name}</option>`).join('')}</select></div></div>${mode==='three'?`<div class="field"><label for="preset">Gợi ý câu hỏi</label><select id="preset"><option value="">Chọn một câu hỏi gợi ý hoặc tự viết bên dưới</option>${questions(flow.topic).map(q=>`<option>${q}</option>`).join('')}</select></div>`:''}${mode!=='daily'?`<div class="field"><label for="question">Câu hỏi của bạn</label><textarea id="question" required minlength="8" maxlength="600" placeholder="Ví dụ: Tôi cần cân nhắc điều gì trước khi thay đổi công việc trong tháng tới?">${E(flow.question)}</textarea><div class="hint">Từ 8–600 ký tự. Câu hỏi mở giúp bạn khám phá lựa chọn rõ hơn.</div></div>`:''}<div class="note">${mode==='daily'?'Mỗi chủ đề có một lá riêng trong ngày, tính theo giờ Việt Nam. Quay lại cùng chủ đề sẽ hiển thị đúng lá đã rút.':'Lá bài là một gợi ý chiêm nghiệm. Bạn luôn là người đưa ra lựa chọn.'} Nhật ký chỉ lưu trên thiết bị này.</div><p id="form-error" class="error" role="alert"></p><div class="form-actions"><span class="badge">✦ Bộ 78 lá · Có lá xuôi & ngược</span><button class="btn" type="submit">${mode==='daily'?'Nhận thông điệp hôm nay':'Xào bài & bắt đầu'} <span>↗</span></button></div></form>`;}
function updateReading(html){$('#reading').innerHTML=html;bindFlow();}
function bindFlow(){const form=$('#draw-form');if(form){$('#topic').addEventListener('change',e=>{flow.topic=e.target.value;const preset=$('#preset');if(preset){preset.innerHTML='<option value="">Chọn một câu hỏi gợi ý hoặc tự viết bên dưới</option>'+questions(flow.topic).map(q=>`<option>${q}</option>`).join('');}});$('#preset')?.addEventListener('change',e=>{if(e.target.value)$('#question').value=e.target.value});form.addEventListener('submit',e=>{e.preventDefault();flow.topic=$('#topic').value;flow.reader=$('#reader').value;flow.question=flow.mode==='daily'?`Thông điệp hôm nay về ${topics.find(t=>t.id===flow.topic).name.toLowerCase()}`:$('#question').value.trim();if(flow.question.length<8||flow.question.length>600){$('#form-error').textContent='Vui lòng viết câu hỏi từ 8–600 ký tự.';return;}if(flow.mode==='daily'){const saved=readStore(`daily:${dayKey()}:${flow.topic}`,null);if(validReading(saved)){flow.result=saved;flow.step=3;updateReading(resultView(saved));return;}}flow.step=2;flow.deck=shuffle();flow.selected=[];updateReading(deckView());});}
$('#reshuffle')?.addEventListener('click',()=>{flow.deck=shuffle();flow.selected=[];updateReading(deckView());$('#deck').classList.add('shuffle-motion')});$('#edit-question')?.addEventListener('click',()=>{flow.step=1;updateReading(flowForm())});document.querySelectorAll('[data-pick]').forEach(b=>b.addEventListener('click',()=>pickCard(Number(b.dataset.pick))));$('#reveal')?.addEventListener('click',reveal);bindResult();}
function deckView(){const count=flow.mode==='three'?3:1;return `${steps()}<div class="result-title"><h2>Chậm lại và chọn ${count===3?'ba':'một'} lá bài.</h2><p>${E(flow.question)}</p></div><div class="selection-status" role="status">Đã chọn ${flow.selected.length}/${count} lá</div><div class="deck" id="deck">${flow.deck.slice(0,24).map((c,i)=>`<button class="deck-card ${flow.selected.some(p=>p.index===i)?'selected':''}" data-pick="${i}" aria-label="Chọn lá bài ${i+1}" ${flow.selected.some(p=>p.index===i)||flow.selected.length>=count?'disabled':''}>${backArt}</button>`).join('')}</div><div class="form-actions"><div><button class="icon-btn" id="edit-question">← Sửa câu hỏi</button><button class="icon-btn" id="reshuffle">⟳ Xào lại</button></div><button class="btn" id="reveal" ${flow.selected.length!==count?'disabled':''}>Lật bài & xem thông điệp ↗</button></div>`;}
function pickCard(index){const count=flow.mode==='three'?3:1;if(flow.selected.length>=count||flow.selected.some(p=>p.index===index))return;flow.selected.push({index,id:flow.deck[index].id,reversed:crypto.getRandomValues(new Uint8Array(1))[0]<64});updateReading(deckView());}
function reveal(){const count=flow.mode==='three'?3:1;if(flow.selected.length!==count)return;flow.result={id:Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join(''),mode:flow.mode,topic:flow.topic,reader:flow.reader,question:flow.question,created:new Date().toISOString(),picks:flow.selected.map(({id,reversed})=>({id,reversed}))};if(flow.mode==='daily')writeStore(`daily:${dayKey()}:${flow.topic}`,flow.result);flow.step=3;updateReading(resultView(flow.result));}
function resultView(r){const persona=readers.find(p=>p.id===r.reader)||readers[0];return `${flow?steps():''}<div class="result-title"><span class="eyebrow">THÔNG ĐIỆP DÀNH CHO BẠN</span><h2>${E(r.question)}</h2><p>${topics.find(t=>t.id===r.topic)?.name} · ${new Date(r.created).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'})}</p></div><div class="spread">${r.picks.map((p,i)=>{const c=cards[p.id];return `<div class="spread-item"><p class="position">${r.picks.length===3?['Bối cảnh','Hiện tại','Hướng đi'][i]:'Lá bài của bạn'}</p>${cardArt(c,p.reversed)}<h3>${c.name}</h3><small>${c.vi} · ${p.reversed?'Đảo ngược':'Xuôi'}</small></div>`}).join('')}</div><div class="note">${persona.icon} Phong cách ${persona.name.toLowerCase()}: ${persona.opening}</div>${r.picks.map((p,i)=>{const d=interpret(p,r.topic,i);return `<div class="result-block"><span class="eyebrow">${r.picks.length===3?['01 · ĐIỀU ĐANG ẢNH HƯỞNG','02 · ĐIỀU CẦN QUAN SÁT','03 · MỘT BƯỚC TIẾP THEO'][i]:'GÓC NHÌN TỪ LÁ BÀI'}</span><h3>${d.card.name} — ${d.card.vi}</h3><p>${d.text}</p><p>${d.context}</p><p class="action">✦ Gợi ý thực hành: ${d.action}</p>${link(cardLink(d.card),'Tìm hiểu lá bài này ↗','text-link')}</div>`}).join('')}<div class="result-toolbar"><button class="btn" id="save-reading">Lưu vào nhật ký</button><button class="btn secondary" id="copy-reading">Sao chép</button><button class="btn secondary" id="download-reading">Tải kết quả</button><button class="btn secondary" id="read-again">Trải bài mới</button></div><p class="hint">Nội dung luận giải được ghép từ thư viện biên soạn theo lá bài và chủ đề; không phân tích ngữ nghĩa câu hỏi như một mô hình AI. Không có người thật đang đọc bài cho bạn.</p>`;}
function bindResult(){const r=flow?.result;if(!r)return;$('#save-reading')?.addEventListener('click',()=>toast(saveReading(r)?'Đã lưu trải bài vào nhật ký trên thiết bị.':'Trình duyệt không cho lưu. Hãy tải kết quả để giữ lại.'));$('#copy-reading')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(readingText(r));toast('Đã sao chép thông điệp.')}catch{toast('Không thể sao chép. Bạn có thể dùng nút Tải kết quả.')}});$('#download-reading')?.addEventListener('click',()=>download(readingText(r),`tarot-goi-mo-${r.id.slice(0,8)}.txt`,'text/plain'));$('#read-again')?.addEventListener('click',()=>{if(flow.mode==='history'){navigate(routes.three);return;}flow=newFlow(flow.mode);updateReading(flowForm())});}
function download(text,name,type){const url=URL.createObjectURL(new Blob([text],{type:`${type};charset=utf-8`}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function library(){title('Ý nghĩa 78 lá bài Tarot');return `<div class="container">${pageHead('THƯ VIỆN TAROT','78 lá bài, 78 cánh cửa.','Khám phá biểu tượng, ý nghĩa xuôi/ngược và lời nhắc thực tế của từng lá bài.')}<div class="search-row"><label class="sr-only" for="card-search">Tìm lá bài</label><input id="card-search" placeholder="Tìm theo tên tiếng Anh, tiếng Việt, từ khóa…" value="${E(librarySearch)}"><select id="suit-filter" aria-label="Lọc bộ bài">${[['all','Tất cả 78 lá'],['major','22 lá Ẩn chính'],['wands','Bộ Gậy · Wands'],['cups','Bộ Cốc · Cups'],['swords','Bộ Kiếm · Swords'],['pentacles','Bộ Tiền · Pentacles']].map(([v,n])=>`<option value="${v}" ${librarySuit===v?'selected':''}>${n}</option>`).join('')}</select></div><div id="library-results">${libraryResults()}</div></div>`;}
const norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').toLowerCase();
function libraryResults(){const filtered=cards.filter(c=>(librarySuit==='all'||c.suit===librarySuit)&&norm(`${c.name} ${c.vi} ${c.keywords}`).includes(norm(librarySearch)));const pages=Math.ceil(filtered.length/18);libraryPage=Math.max(1,Math.min(libraryPage,pages||1));return `<p class="hint" role="status">${filtered.length} lá bài${pages>1?` · Trang ${libraryPage}/${pages}`:''}</p>${filtered.length?`<div class="library-grid">${filtered.slice((libraryPage-1)*18,libraryPage*18).map(c=>link(cardLink(c),`${cardArt(c)}<strong>${c.name}</strong><small>${c.vi}</small>`,'library-card')).join('')}</div>`:'<div class="empty"><h2>Chưa tìm thấy lá bài.</h2><p>Thử một từ khóa ngắn hơn hoặc chọn Tất cả 78 lá.</p></div>'}${pages>1?`<div class="pagination"><button class="btn secondary" id="prev-page" ${libraryPage===1?'disabled':''}>← Trang trước</button><button class="btn secondary" id="next-page" ${libraryPage===pages?'disabled':''}>Trang tiếp →</button></div>`:''}`;}
function bindLibrary(){const refresh=()=>{$('#library-results').innerHTML=libraryResults();bindPagination();};$('#card-search')?.addEventListener('input',e=>{librarySearch=e.target.value;libraryPage=1;refresh()});$('#suit-filter')?.addEventListener('change',e=>{librarySuit=e.target.value;libraryPage=1;refresh()});bindPagination();}
function bindPagination(){$('#prev-page')?.addEventListener('click',()=>{libraryPage--;$('#library-results').innerHTML=libraryResults();bindPagination();$('#card-search').scrollIntoView({block:'center'})});$('#next-page')?.addEventListener('click',()=>{libraryPage++;$('#library-results').innerHTML=libraryResults();bindPagination();$('#card-search').scrollIntoView({block:'center'})});}
function detail(id){const c=cards[id];if(!c)return notFound();title(`Lá bài ${c.name}: ý nghĩa xuôi và ngược`);return `<div class="container"><p style="margin-top:30px">${link(routes.library,'← Trở về thư viện','text-link')}</p><div class="detail-layout"><div class="detail-visual">${cardArt(c)}</div><article><span class="eyebrow">${c.group} · NGUYÊN TỐ ${c.element}</span><h1>${c.name}<br><em>${c.vi}</em></h1><p>${c.keywords}</p><h2>Ý nghĩa khi xuôi</h2><p>${c.upright}</p><h2>Ý nghĩa khi đảo ngược</h2><p>${c.reversed}</p><h2>Một điều có thể thực hành</h2><p>${c.action}</p><h2>Đặt lá bài vào bối cảnh của bạn</h2><p>Trong tình cảm, hãy nhìn vào cách giao tiếp và ranh giới. Trong công việc, đối chiếu với kỹ năng và phản hồi thực tế. Với nguồn lực, chú ý ngân sách và mức rủi ro thay vì coi lá bài là lời hứa về kết quả.</p><div class="result-toolbar">${link(routes.custom,'Đặt câu hỏi với Tarot ↗','btn')}${link(cardLink(cards[(c.id+1)%78]),'Lá tiếp theo →','btn secondary')}</div><p class="hint">Minh họa biểu tượng nguyên bản của Tarot Gợi Mở. Nội dung dùng cho mục đích chiêm nghiệm.</p></article></div></div>`;}
function readerPage(){title('Phong cách luận giải Tarot');return `<div class="container">${pageHead('BA CÁCH LẮNG NGHE','Chọn nhịp điệu phù hợp với bạn.','Đây là ba phong cách đọc tự động từ cùng thư viện Tarot, không phải hồ sơ của chuyên gia hay dịch vụ tư vấn trực tiếp.')}<section style="padding-top:10px"><div class="reader-grid">${readers.map(r=>`<article class="reader"><span class="mode-icon">${r.icon}</span><h2>${r.name}</h2><strong>${r.subtitle}</strong><p>${r.text}</p>${link(`${routes.custom}?reader=${r.id}`,`Chọn phong cách này ↗`,'btn secondary')}</article>`).join('')}</div></section></div>`;}
function historyPage(){title('Nhật ký trải bài');const data=history();return `<div class="container">${pageHead('NHỮNG ĐIỀU BẠN MUỐN GIỮ LẠI','Nhật ký của riêng bạn.','Được lưu trong trình duyệt trên thiết bị này. Không có đồng bộ tài khoản; hãy xuất bản sao nếu bạn muốn giữ lâu dài.')}<div class="section-head"><p>${data.length}/100 trải bài được lưu</p><div><button id="export-history" class="icon-btn" ${data.length?'':'disabled'}>↓ Xuất JSON</button><button id="clear-history" class="icon-btn" ${data.length?'':'disabled'}>Xóa nhật ký</button></div></div>${data.length?`<div class="history-list">${data.map(r=>`<article class="history-item"><div class="row"><small>${new Date(r.created).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'})} · ${topics.find(t=>t.id===r.topic).name}</small><button class="icon-btn" data-delete="${r.id}" aria-label="Xóa trải bài ${E(r.question)}">Xóa</button></div><h3>${E(r.question)}</h3><p>${r.picks.map(p=>`${cards[p.id].name}${p.reversed?' (ngược)':''}`).join(' · ')}</p><button class="btn secondary" data-open="${r.id}">Đọc lại thông điệp ↗</button></article>`).join('')}</div>`:`<div class="empty"><span class="mode-icon" style="margin:0 auto 20px">✎</span><h2>Trang đầu tiên vẫn đang chờ bạn.</h2><p>Trải bài rồi bấm “Lưu vào nhật ký” để giữ lại điều bạn muốn suy ngẫm.</p>${link(routes.three,'Bắt đầu một trải bài ↗','btn')}</div>`}</div>`;}
function bindHistory(){document.querySelectorAll('[data-open]').forEach(b=>b.addEventListener('click',()=>{const r=history().find(r=>r.id===b.dataset.open);if(!r)return;flow={mode:'history',step:3,result:r};root.innerHTML=`<div class="container">${pageHead('NHẬT KÝ','Một thông điệp đã lưu.','Dành một chút thời gian để nhìn lại điều đã thay đổi.')}<div class="reading-shell">${resultView(r)}<p style="margin-top:20px">${link(routes.history,'← Trở về nhật ký','text-link')}</p></div></div>`;bindResult();window.scrollTo(0,0)}));document.querySelectorAll('[data-delete]').forEach(b=>b.addEventListener('click',()=>{writeStore('history',history().filter(r=>r.id!==b.dataset.delete));root.innerHTML=historyPage();bindHistory();toast('Đã xóa trải bài.')}));$('#clear-history')?.addEventListener('click',()=>{if(!confirm('Xóa toàn bộ nhật ký trên thiết bị này? Bạn có thể xuất JSON trước để sao lưu.'))return;writeStore('history',[]);root.innerHTML=historyPage();bindHistory();toast('Đã xóa nhật ký. Các lá hằng ngày vẫn được giữ riêng.')} );$('#export-history')?.addEventListener('click',()=>download(JSON.stringify({version:1,exportedAt:new Date().toISOString(),readings:history()},null,2),`tarot-nhat-ky-${dayKey()}.json`,'application/json'));}
function blog(slug){const a=articles.find(a=>a.slug===slug);if(slug&&!a)return notFound();title(a?a.title:'Góc chiêm nghiệm Tarot');return a?`<div class="container"><div class="narrow">${pageHead(a.tag,a.title,a.intro)}<p>${link(routes.blog,'← Tất cả bài viết','text-link')}</p>${a.sections.map(([h,p])=>`<h2>${h}</h2><p>${p}</p>`).join('')}<div class="note">Biên soạn bởi Tarot Gợi Mở · Nội dung hướng dẫn tự chiêm nghiệm, không phải tư vấn chuyên môn.</div>${link(routes.three,'Thử trải bài 3 lá ↗','btn')}</div></div>`:`<div class="container">${pageHead('GÓC CHIÊM NGHIỆM','Chậm lại để hiểu nhiều hơn.','Hướng dẫn thực hành, khám phá biểu tượng và giữ một khoảng cách lành mạnh với các trải bài.')}<section style="padding-top:10px">${articleCards(articles)}</section></div>`;}
function info(privacy){title(privacy?'Quyền riêng tư':'Về Tarot Gợi Mở');return `<div class="container"><div class="narrow">${pageHead('TAROT GỢI MỞ',privacy?'Không gian riêng của bạn.':'Lá bài gợi mở. Bạn chọn hướng đi.','Một ứng dụng Tarot tiếng Việt dành cho việc chiêm nghiệm.')}<h2>${privacy?'Dữ liệu được lưu ở đâu?':'Gợi Mở hoạt động như thế nào?'}</h2><p>${privacy?'Câu hỏi, các lá đã rút và nhật ký được lưu trong localStorage của trình duyệt khi bạn dùng chức năng lưu hoặc rút bài hằng ngày. Dữ liệu này không được gửi đến máy chủ luận giải và không có đồng bộ đa thiết bị. Nếu dùng máy chung, người khác có thể xem dữ liệu trong cùng trình duyệt.':'Bộ 78 lá gồm 22 lá Ẩn chính và 56 lá Ẩn phụ, với nội dung xuôi/ngược. Ứng dụng xào bài ngẫu nhiên bằng Web Crypto; các chế độ chọn thêm bối cảnh theo chủ đề và một lời mở đầu theo phong cách đọc. Không có chuyên gia trực tiếp hay dịch vụ AI bên ngoài đang phân tích câu hỏi.'}</p><h2>${privacy?'Dịch vụ bên ngoài':'Chi phí và thanh toán'}</h2><p>${privacy?'Website được phục vụ qua Vercel và có tải phông chữ từ Google Fonts. Nhà cung cấp hạ tầng có thể xử lý dữ liệu kỹ thuật như địa chỉ IP theo chính sách của họ. Ứng dụng không tích hợp quảng cáo, công cụ phân tích hành vi hay thanh toán.':'Các chế độ đọc hiện tại miễn phí. Ứng dụng không thu tiền, không xác nhận chuyển khoản và không phát hành mã mở khóa. Nếu sau này có dịch vụ trả phí, thông tin và điều khoản sẽ cần được công bố trước khi triển khai.'}</p><h2>${privacy?'Xuất và xóa dữ liệu':'Hiểu đúng về thông điệp'}</h2><p>${privacy?'Bạn có thể xuất nhật ký dưới dạng JSON và xóa từng trải bài hoặc toàn bộ nhật ký ở trang Nhật ký. Để xóa cả các lá hằng ngày, hãy dùng chức năng xóa dữ liệu trang web trong cài đặt trình duyệt. Chế độ riêng tư hoặc việc xóa dữ liệu trình duyệt có thể làm mất dữ liệu.':'Tarot không xác minh được suy nghĩ của người khác và không bảo đảm kết quả trong tương lai. Các thông điệp nhằm giúp bạn đặt câu hỏi và cân nhắc hành động. Với sức khỏe, pháp lý hoặc tài chính, hãy dùng nguồn thông tin và chuyên gia phù hợp.'}</p>${link(privacy?routes.history:routes.three,privacy?'Mở nhật ký ↗':'Bắt đầu trải bài ↗','btn')}</div></div>`;}
function notFound(){title('Không tìm thấy trang');return `<div class="container">${pageHead('404','Trang này chưa có trong hành trình.','Bạn có thể quay về trang chủ hoặc khám phá thư viện 78 lá bài.')}<div class="empty">${link('/','Về trang chủ','btn')}</div></div>`;}
function render(){flow=null;const path=location.pathname.replace(/\/+$/,'')||'/';let html;if(path==='/')html=home();else if(path==='/boi-tarot')html=readingPage('three');else if(path==='/boi-bai-tarot-hom-nay')html=readingPage('daily');else if(path==='/boi-bai-tarot-chuyen-sau')html=readingPage('custom');else if(path==='/y-nghia-78-la-bai-tarot')html=library();else if(/^\/la-bai\/\d+$/.test(path))html=detail(Number(path.split('/')[2]));else if(path==='/cac-tarot-reader')html=readerPage();else if(path==='/nhat-ky')html=historyPage();else if(path==='/huong-dan'||path.startsWith('/huong-dan/'))html=blog(path.split('/')[2]);else if(path==='/gioi-thieu'||path==='/quyen-rieng-tu')html=info(path==='/quyen-rieng-tu');else html=notFound();root.innerHTML=html;document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')===location.pathname));document.querySelector('nav').classList.remove('open');$('.menu').setAttribute('aria-expanded','false');bindFlow();bindLibrary();bindHistory();}
function navigate(url){window.history.pushState({},'',url);render();window.scrollTo(0,0);root.focus({preventScroll:true});}
document.querySelector('#site-header').innerHTML=header();document.querySelector('#site-footer').innerHTML=footer();$('.menu').addEventListener('click',()=>{const open=$('nav').classList.toggle('open');$('.menu').setAttribute('aria-expanded',String(open))});document.addEventListener('click',e=>{const a=e.target.closest('a[data-link]');if(!a||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;if(a.origin!==location.origin)return;e.preventDefault();navigate(a.href)});window.addEventListener('popstate',()=>render());render();
